276	/** Project work against account-wide consumption, aligned on one shared UTC bucket domain. */
277	export function usageComparisonRows(source: LoadedStatsSource, controls: StatsControls, options: StatsOptions): StatsChartRow[] {
278	    const granularity = controls.usageGranularity;
279	    const accountRows = source.accountRows.filter(({ recordedAt }) => inRange(recordedAt, controls));
280	    const tokenRows = source.tokenRows.filter(({ recordedAt }) => inRange(recordedAt, controls));
281	    const actions = source.stats.actions.filter(({ completedAt }) => inRange(completedAt, controls));
282	    const seriesOptions = visibleAccountSeries(accountRows, options);
283	    const visibleSeriesIdentities = new Set(seriesOptions.map(({ identity }) => identity));
284	    const timestamps = [
285	        ...actions.map(({ completedAt }) => completedAt),
286	        ...tokenRows.map(({ recordedAt }) => recordedAt),
287	        ...accountRows.flatMap((row) => (
288	            visibleSeriesIdentities.has(accountSeriesIdentity(row)) && hasUsableDelta(row) ? [row.recordedAt] : []
289	        )),
290	    ];
291	    const contexts = bucketContexts(bucketDomain(timestamps, granularity, controls), granularity);
292	    const indexes = buildComparisonIndexes(accountRows, tokenRows, actions, granularity);
293	
294	    return [
295	        ...comparisonAccountRows(contexts, granularity, seriesOptions, indexes),
296	        ...projectTokenRows(contexts, granularity, source.tokenTimeAvailable, indexes),
297	        ...ratioRows(contexts, granularity, 'tokensPerAccountUsage', seriesOptions, indexes),
298	        ...ratioRows(contexts, granularity, 'actionsPerAccountUsage', seriesOptions, indexes),
299	        ...contexts.flatMap((context) => activityCountRows(context, granularity, indexes.actionsByBucket.get(context.start) ?? [])),
300	    ];
301	}
