18	function isCountedConversation(conversation: StatsConversationFact, controls: StatsControls) {
19	    if (controls.totalsMetric === 'duration') {
20	        return TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
21	            && conversation.completedAt !== null
22	            && inRange(conversation.completedAt, controls);
23	    }
24	    if (!controls.startUtc && !controls.endUtc) return true;
25	
26	    return conversation.completedAt !== null && inRange(conversation.completedAt, controls);
27	}
